// Verify the exact RelayOS request body before processing it.
// Configure RELAYOS_WEBHOOK_SECRET in the n8n host environment and set
// NODE_FUNCTION_ALLOW_BUILTIN=crypto. RelayOS signs timestamp.nonce.rawBody.

const input = $input.first().json;
const headers = input.headers ?? {};
const signature = headers["x-relayos-signature"];
const timestamp = headers["x-relayos-timestamp"];
const nonce = headers["x-relayos-nonce"];
const rawBody = typeof input.rawBody === "string" ? input.rawBody : Buffer.from(input.rawBody ?? "").toString("utf8");
const secret = $env.RELAYOS_WEBHOOK_SECRET;

if (!signature || !timestamp || !nonce || !/^v1=[0-9a-f]{64}$/.test(signature)) {
  throw new Error("Missing or malformed RelayOS signature headers");
}
if (!/^\d+$/.test(timestamp)) throw new Error("Invalid RelayOS timestamp");
const requestTime = Number(timestamp);
if (!Number.isSafeInteger(requestTime) || Math.abs(Math.floor(Date.now() / 1000) - requestTime) > 300) {
  throw new Error("RelayOS timestamp is outside the five-minute replay window");
}
if (!rawBody || !secret) throw new Error("Raw body or RELAYOS_WEBHOOK_SECRET is missing");

const crypto = require("crypto");
const canonical = `${timestamp}.${nonce}.${rawBody}`;
const expected = `v1=${crypto.createHmac("sha256", secret).update(canonical).digest("hex")}`;
const actualBuffer = Buffer.from(signature, "utf8");
const expectedBuffer = Buffer.from(expected, "utf8");
if (actualBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(actualBuffer, expectedBuffer)) {
  throw new Error("Invalid RelayOS signature");
}

return [{ json: input.body }];

